/* Generated bytes stay on device; Android receives data, never a blob URL. */
(function(){'use strict';if(window.HAFileDownload)return;const base=new URL('./',document.currentScript.src),loading=new Map();let tail=Promise.resolve();
function filename(value){return String(value||'HA-file').replace(/[\\/\u0000-\u001f\u007f:*?"<>|]/g,'-').trim().slice(0,170)||'HA-file';}
function mime(blob,name){const raw=String(blob.type||'').split(';')[0];if(/^[\w.+-]+\/[\w.+-]+$/.test(raw))return raw;return ({pdf:'application/pdf',txt:'text/plain',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',csv:'text/csv',json:'application/json',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})[name.split('.').pop().toLowerCase()]||'application/octet-stream';}
function load(file,test){if(test())return Promise.resolve();if(loading.has(file))return loading.get(file);const p=new Promise((resolve,reject)=>{const script=document.createElement('script'),timer=setTimeout(()=>fail(),12000);function fail(){clearTimeout(timer);script.remove();reject(Error('أداة تجهيز الملف لم تتحمّل. أعد فتح الصفحة، وتأكد من رفع ملفات التعديل كاملة.'))}script.src=new URL(file,base).href;script.onload=()=>{clearTimeout(timer);if(test())resolve();else fail()};script.onerror=fail;document.head.append(script)}).finally(()=>loading.delete(file));loading.set(file,p);return p;}
async function ensure(kind){if(kind==='pdf'){await Promise.all([load('ha-vendor-html2canvas.js',()=>typeof window.html2canvas==='function'),load('ha-vendor-jspdf.js',()=>!!window.jspdf?.jsPDF)])}else if(kind==='word')await load('ha-vendor-jszip.js',()=>!!window.JSZip);}
async function native(){if(typeof window.HAAndroid?.saveBase64File==='function')return window.HAAndroid;if(!/HAAndroid\/|\bwv\b/.test(navigator.userAgent))return null;await new Promise(resolve=>{const finish=()=>{clearTimeout(timer);removeEventListener('ha:native-ready',finish);resolve()};const timer=setTimeout(finish,1800);addEventListener('ha:native-ready',finish,{once:true})});if(typeof window.HAAndroid?.saveBase64File!=='function')throw Error('ربط حفظ الملفات داخل التطبيق غير جاهز. أغلق التطبيق وافتحه؛ إذا استمرت الرسالة تحتاج مراجعة نسخة التطبيق.');return window.HAAndroid;}
function asData(blob,type){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('تعذرت قراءة الملف من الجهاز؛ أعد تجهيز الملف.'));reader.onabort=()=>reject(Error('توقفت قراءة الملف.'));reader.onload=()=>{const data=reader.result;if(typeof data!=='string'||!data.includes(';base64,'))return reject(Error('تعذر تجهيز بيانات الملف للحفظ.'));resolve(data)};reader.readAsDataURL(blob.type?blob:new Blob([blob],{type}));});}
async function perform(blob,name){if(!(blob instanceof Blob)||blob.size===0)throw Error('الملف الناتج فارغ؛ أعد تجهيز النتيجة قبل التنزيل.');name=filename(name);const type=mime(blob,name),api=await native();if(api){if(blob.size>40*1024*1024)throw Error('حجم الملف أكبر من حد الحفظ داخل التطبيق (40 MB). جزّئ الملف أو نزّل نتيجة أصغر.');const data=await asData(blob,type);const result=await api.saveBase64File(data,name,type);if(result===false||result?.error||result?.ok===false)throw Error(String(result?.error||'تعذر تسليم الملف للحفظ داخل التطبيق.'));return {method:'android',status:'requested'};}
 const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.rel='noopener';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),120000);return {method:'browser',status:'requested'};}
function save(blob,name){const task=tail.then(()=>perform(blob,name));tail=task.catch(()=>{});return task;}
window.HAFileDownload={save,ensure};})();
